import java.util.Scanner;

public class Main {
    static final int MAX_LIMIT = 100005;
    static final long BIG_MOD = 1000000007L;
    static long[] precomputed = new long[17];

    static long process(long val, int level) {
        if (level == 0) {
            return (val == 0) ? 0 : BIG_MOD;
        }
        long times = val / precomputed[level];
        if (val % precomputed[level] == 0) {
            return level * times;
        }
        long candidate1 = process(Math.abs(val - precomputed[level] * (times + 1)), level - 1) + level;
        long candidate2 = process(val - precomputed[level] * times, level - 1);
        return Math.min(level * (times + 1) + candidate1 - level, level * times + candidate2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        precomputed[1] = 1;
        for (int i = 2; i < 17; ++i) {
            precomputed[i] = precomputed[i - 1] * 10 + 1;
        }
        long number = scanner.nextLong();
        System.out.println(process(number, 16));
        scanner.close();
    }
}
